def _get_factory(func, kwargs):
    """Get the factory for merge/merge_with from kwargs."""
    factory = kwargs.get('factory', None)
    if factory is None:
        # Check if func has a __defaults__ with factory at end
        defaults = getattr(func, '__defaults__', ())
        if defaults and len(defaults) >= 1:
            factory = defaults[-1]
    return factory
